using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "DiceSecondActionLogic_NoTarget", menuName = "Data/Battle/Logics/Dice Action/Dice Second Action Logic/DiceSecondActionLogic_NoTarget")]
public class DiceSecondActionLogic_NoTarget : DiceSecondActionLogic
{
	public override void OnDrop(ActionFace actionFace, GameObject target, GameObject source)
	{
		if (actionFace.SecondActionValue == EffectsValues.NO_VALUE)
		{
			actionFace.SecondBattleAction.Cast(source);
		}
		else
		{
			actionFace.SecondBattleAction.CastAmount(actionFace.SecondModifiedActionValue, source);
		}
	}
}
